	modelSettings: zod_v4.z.record(zod_v4.z.string(), zod_v4.z.unknown()).optional().describe("Model settings (temperature, etc.)"),
	providerOptions: zod_v4.z.record(zod_v4.z.string(), zod_v4.z.record(zod_v4.z.string(), zod_v4.z.unknown()).optional()).optional().describe("Provider-specific options"),
	blockAfter: zod_v4.z.number().optional().describe("Token threshold for synchronous blocking"),
